const body = $input.first().json.body;
const url = body.url || 'https://raw.githubusercontent.com/JeffSackmann/tennis_atp/master/atp_matches_2024.csv';
return [{ json: { url } }];

const text = $input.first().json.data;
const lines = text.split('\n').filter(l => l.trim());
if (lines.length < 2) return [{ json: { error: 'CSV too short' } }];
const headers = lines[0].split(',').map(h => h.trim());
const rows = lines.slice(1).map(line => {
  const vals = line.split(',');
  const row = {};
  headers.forEach((h, i) => { row[h] = (vals[i] || '').trim(); });
  return row;
});
const playerMap = new Map();
for (const row of rows) {
  if (row.winner_id && row.winner_name) playerMap.set(row.winner_id, { name: row.winner_name, country: row.winner_ioc || '', hand: row.winner_hand || 'R' });
  if (row.loser_id && row.loser_name) playerMap.set(row.loser_id, { name: row.loser_name, country: row.loser_ioc || '', hand: row.loser_hand || 'R' });
}
return [{ json: { players: Object.fromEntries(playerMap), rows: rows.length, playerCount: playerMap.size } }];
